es, nama Indonesia telah terekam, tidak dapat ditukar kembali dengan \"Indes-netherlandies\"',1,NULL,NULL,NULL,NULL,NULL,NULL),(41614,45574,'a','Sejarah Indonesia',1,NULL,NULL,NULL,NULL,NULL,NULL),(41615,45578,'a','9786026947949',1,NULL,NULL,NULL,NULL,NULL,NULL),(41616,45579,'0','010-1025001135',1,NULL,NULL,NULL,NULL,NULL,NULL),(41617,45580,'a','id',1,NULL,NULL,NULL,NULL,NULL,NULL),(41618,45581,'a','629.2',1,NULL,NULL,NULL,NULL,NULL,NULL),(41619,45582,'a','629.2 NUG p',1,NULL,NULL,NULL,NULL,NULL,NULL),(41620,45583,'a','ARIF WAHYU NUGRAHA, S.Pd., M.T',1,NULL,NULL,NULL,NULL,NULL,NULL),(41621,45584,'a','Pemeliharaan Kelistrikan Kendaraan Ringan : Untuk SMK / MAK Kelas XI',1,NULL,NULL,NULL,NULL,NULL,NULL),(41622,45585,'a','Malang',1,NULL,NULL,NULL,NULL,NULL,NULL),(41623,45585,'b','PT. Latif Kitto Mahesa',2,NULL,NULL,NULL,NULL,NULL,NULL),(41624,45585,'c','2018',3,NULL,NULL,NULL,NULL,NULL,NULL),(41625,45586,'a','vi, 172 hlm; 23,5cm',1,NULL,NULL,NULL,NULL,NULL,NULL),(41626,45587,'a','teknik otomotif -- Kelistrikan -- Pemeliharaan -- Kendaraan Ringan',1,NULL,NULL,NULL,NULL,NULL,NULL),(41627,45591,'a','978-602-6947-75-8',1,NULL,NULL,NULL,NULL,NULL,NULL),(41628,45592,'0','010-1025001136',1,NULL,NULL,NULL,NULL,NULL,NULL),(41629,45593,'a','id',1,NULL,NULL,NULL,NULL,NULL,NULL),(41630,45594,'a','629.2',1,NULL,NULL,NULL,NULL,NULL,NULL),(41631,45595,'a','629.2',1,NULL,NULL,NULL,NULL,NULL,NULL),(41632,45596,'a','PPPPTK BOE',1,NULL,NULL,NULL,NULL,NULL,NULL),(41633,45597,'a','Gambar Teknik Otomotif',1,NULL,NULL,NULL,NULL,NULL,NULL),(41634,45598,'a','1',1,NULL,NULL,NULL,NULL,NULL,NULL),(41635,45599,'a','Malang',1,NULL,NULL,NULL,NULL,NULL,NULL),(41636,45599,'b','PT. Latif Kitto Mahesa',2,NULL,NULL,NULL,NULL,NULL,NULL),(41637,45599,'c','2018',3,NULL,NULL,NULL,NULL,NULL,NULL),(41638,45600,'a','v, 127 hlm, 25 cm',1,NULL,NULL,NULL,NULL,NULL,NULL),(41639,45601,'a','Otomotif -- teknik otomotif',1,NULL,NULL,NULL,NULL,NULL,NULL),(41640,45605,'a','9795263447',1,NULL,NULL,NULL,NULL,NULL,NULL),(41