m dilema cinta segitiga. Pertanyaan besar pun menuntut jawab : mana yang patut Zach perjuangkan; Maura atau Maghali ? Mampukan yang tak terpilih merelakan keadaan ?',1,NULL,NULL,NULL,NULL,NULL,NULL),(48962,53537,'a','novel',1,NULL,NULL,NULL,NULL,NULL,NULL),(48963,53541,'a','9786020328652',1,NULL,NULL,NULL,NULL,NULL,NULL),(48964,53542,'0','010-1025001713',1,NULL,NULL,NULL,NULL,NULL,NULL),(48965,53543,'a','id',1,NULL,NULL,NULL,NULL,NULL,NULL),(48966,53544,'a','813',1,NULL,NULL,NULL,NULL,NULL,NULL),(48967,53545,'a','813 DYA I',1,NULL,NULL,NULL,NULL,NULL,NULL),(48968,53546,'a','Irene Dyah',1,NULL,NULL,NULL,NULL,NULL,NULL),(48969,53547,'a','Love In Blue City',1,NULL,NULL,NULL,NULL,NULL,NULL),(48970,53548,'a','Jakarta',1,NULL,NULL,NULL,NULL,NULL,NULL),(48971,53548,'b','PT Gramedia Pustaka Utama',2,NULL,NULL,NULL,NULL,NULL,NULL),(48972,53548,'c','2016',3,NULL,NULL,NULL,NULL,NULL,NULL),(48973,53549,'a','xi, 219 hlm; 20 cm',1,NULL,NULL,NULL,NULL,NULL,NULL),(48974,53550,'a','novel -- Romantis -- Love In Blue City',1,NULL,NULL,NULL,NULL,NULL,NULL),(48975,53554,'0','010-1025001714',1,NULL,NULL,NULL,NULL,NULL,NULL),(48976,53555,'a','id',1,NULL,NULL,NULL,NULL,NULL,NULL),(48977,53556,'a','NONE',1,NULL,NULL,NULL,NULL,NULL,NULL),(48978,53557,'a','FIK Sam s',1,NULL,NULL,NULL,NULL,NULL,NULL),(48979,53558,'a','Samadi',1,NULL,NULL,NULL,NULL,NULL,NULL),(48980,53559,'a','Senandung Hidup',1,NULL,NULL,NULL,NULL,NULL,NULL),(48981,53560,'a','1',1,NULL,NULL,NULL,NULL,NULL,NULL),(48982,53561,'a','Medan',1,NULL,NULL,NULL,NULL,NULL,NULL),(48983,53561,'b','PT DUNIA PUSTAKA JAYA',2,NULL,NULL,NULL,NULL,NULL,NULL),(48984,53561,'c','1941',3,NULL,NULL,NULL,NULL,NULL,NULL),(48985,53562,'a','70 hlm; 21 cm',1,NULL,NULL,NULL,NULL,NULL,NULL),(48986,53563,'a','Sajak',1,NULL,NULL,NULL,NULL,NULL,NULL),(48987,53567,'a','9789792904253',1,NULL,NULL,NULL,NULL,NULL,NULL),(48988,53568,'0','010-1025001715',1,NULL,NULL,NULL,NULL,NULL,NULL),(48989,53569,'a','id',1,NULL,NULL,NULL,NULL,NULL,NULL),(48990,53570,'a','693.54