INSERT INTO `memberrules` VALUES (1,'Persyaratan','<ul>                <li>Minimal berusia 5 tahun&nbsp;</li>                <li>Warga negara Indonesia<br></li>                <li>Menunjukkan tanda pengenal atau Kartu Keluarga bagi anak usia pra sekolah</li>            </ul>','',4,NULL,'2013-12-29 11:01:50','192.168.101.59',NULL,'2016-02-29 18:09:30','192.168.0.1'),(3,'Tata Tertib','<ul>            <li>Kartu anggota harus dibawa setiap kali berkunjung</li>            <li>Kartu anggota tidak boleh dipinjamkan kepada orang lain</li>            <li>Jika kartu anggota&nbsp;hilang, wajib membawa surat keterangan dari pihak berwenang untuk penggantiannya</li>            </ul>','',2,NULL,'2013-06-18 15:04:49','192.168.16.38',NULL,'2016-02-29 18:10:26','192.168.0.1');
/*!40000 ALTER TABLE `memberrules` ENABLE KEYS */;
